<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/helpers/pkl-schedules.php';
$user=require_role('admin','staf_bkk');pkl_schedules_require_ready();
try{[$filters,$where,$params]=pkl_schedule_filters($_GET,true);}catch(InvalidArgumentException $exception){http_response_code(400);exit(e($exception->getMessage()));}
$from=' FROM pkl_business_trips a JOIN pkl_placements p ON p.id=a.placement_id JOIN siswa s ON s.id=p.siswa_id WHERE '.$where;
$summary=panel_query("SELECT COUNT(*) AS total,COALESCE(SUM(CASE WHEN a.sumber_biaya='sekolah' THEN a.nominal ELSE 0 END),0) AS sekolah,COALESCE(SUM(CASE WHEN a.sumber_biaya='pribadi' THEN a.nominal ELSE 0 END),0) AS pribadi".$from,$params)->fetch();
$total=(int)$summary['total'];$pages=max(1,(int)ceil($total/10));$page=min($pages,positive_id($_GET['page']??'1')??1);
$rows=panel_query('SELECT a.*,p.tanggal_mulai,p.tanggal_selesai,s.nama,s.nis'.$from.' ORDER BY a.tanggal DESC,a.id DESC LIMIT :limit OFFSET :offset',$params+['limit'=>10,'offset'=>($page-1)*10])->fetchAll();
$periods=pkl_period_options();
panel_start($user,'Perjalanan dinas & biaya','biaya-perjalanan');
?>
<div class="trip-workspace">
<header class="page-actions"><div><h1><?= panel_icon('location') ?> Perjalanan dinas &amp; biaya PKL</h1><p>Catat perjalanan petugas terkait penempatan PKL dan nominal biayanya.</p></div><div class="trip-actions"><a class="trip-primary" href="<?= e(base_url('panel/biaya-perjalanan/form.php?'.http_build_query(['placement_id'=>$filters['placement_id']]))) ?>"><?= panel_icon('add') ?> Catat perjalanan</a><a href="<?= e(base_url('panel/pkl/jadwal.php')) ?>"><?= panel_icon('calendar') ?> Jadwal PKL</a><a href="<?= e(base_url('panel/biaya-perjalanan/unduh.php?'.http_build_query($filters))) ?>"><?= panel_icon('download') ?> Ekspor biaya</a></div></header>
<details class="trip-help"><summary><?= panel_icon('view') ?> Cara menggunakan</summary><ol><li>Pilih penempatan siswa melalui <strong>Catat perjalanan</strong>.</li><li>Isi tanggal perjalanan, tujuan, petugas, nominal, dan sumber biaya. Hubungkan ke jadwal monitoring bila ada.</li><li>Simpan catatan, lalu gunakan filter untuk melihat rekap atau mengekspor Excel.</li></ol><p>Satu catatan terkait satu penempatan. Jika satu perjalanan mengunjungi beberapa siswa, jangan mencatat seluruh biaya yang sama berulang kali; masukkan alokasi biaya per catatan agar total tidak berlipat. Catatan biaya ini tidak otomatis menandai monitoring selesai.</p></details>
<form class="filter-form card trip-filter" method="get">
<?php if($filters['placement_id']!==''): ?><input type="hidden" name="placement_id" value="<?= e($filters['placement_id']) ?>"><p class="trip-filter-context">Hanya perjalanan pada penempatan #<?= e($filters['placement_id']) ?>. Reset untuk melihat semua penempatan.</p><?php endif; ?>
<label for="trip-period">Periode penempatan PKL<select id="trip-period" name="periode"><option value="">Semua periode</option><?php foreach($periods as $period):$value=$period['tanggal_mulai'].'_'.$period['tanggal_selesai']; ?><option value="<?= e($value) ?>" <?= $filters['periode']===$value?'selected':'' ?>><?= e($period['tanggal_mulai'].' - '.$period['tanggal_selesai']) ?></option><?php endforeach; ?></select></label>
<label for="trip-week">Minggu perjalanan <small>Opsional; pilih tanggal dalam minggu</small><input id="trip-week" type="date" name="minggu" value="<?= e($filters['minggu']) ?>"></label><button type="submit"><?= panel_icon('search') ?> Terapkan</button><a href="<?= e(base_url('panel/biaya-perjalanan/')) ?>"><?= panel_icon('reset') ?> Reset</a>
</form>
<p class="trip-scope"><?php if($filters['minggu']!==''): ?>Tanggal perjalanan <?= e($params['senin'].' sampai '.$params['minggu']) ?> (Senin-Minggu).<?php else: ?>Semua tanggal perjalanan.<?php endif; ?> Total dan ekspor mengikuti filter, mencakup seluruh halaman.</p>
<div class="trip-totals"><div><span><?= panel_icon('program') ?> Biaya dari sekolah</span><strong><?= e(pkl_rupiah((string)$summary['sekolah'])) ?></strong></div><div><span><?= panel_icon('akun') ?> Biaya pribadi</span><strong><?= e(pkl_rupiah((string)$summary['pribadi'])) ?></strong></div></div>
<div class="trip-list-heading"><h2><?= panel_icon('lamaran') ?> Daftar perjalanan</h2><span><?= $total ?> catatan &middot; Halaman <?= $page ?> dari <?= $pages ?></span></div>
<div class="table-scroll trip-sheet" data-vertical-list tabindex="0" role="region" aria-label="Daftar perjalanan dan biaya, gulir untuk melihat data"><table><thead><tr><th>Siswa / periode PKL</th><th>Tanggal perjalanan</th><th>Tujuan / petugas</th><th>Biaya / sumber</th><th>Monitoring terkait</th><th>Tindakan</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= e($row['nama']) ?></strong><small><?= e($row['tanggal_mulai'].' - '.$row['tanggal_selesai']) ?></small></td><td><?= e($row['tanggal']) ?></td><td><?= e($row['tujuan']) ?><small><?= e($row['petugas']) ?></small></td><td><strong><?= e(pkl_rupiah($row['nominal'])) ?></strong><small><?= e(ucfirst($row['sumber_biaya'])) ?></small></td><td><?php if($row['monitoring_id']): ?><a href="<?= e(base_url('panel/pkl/jadwal-form.php?id='.$row['monitoring_id'])) ?>">Monitoring #<?= (int)$row['monitoring_id'] ?></a><?php else: ?><span class="muted">Tidak dikaitkan</span><?php endif; ?></td><td><a class="trip-edit" href="<?= e(base_url('panel/biaya-perjalanan/form.php?id='.$row['id'])) ?>"><?= panel_icon('edit') ?> Edit</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty-panel"><?php if($filters['periode']!==''||$filters['minggu']!==''||$filters['placement_id']!==''): ?>Tidak ada perjalanan yang sesuai. Ubah filter atau reset untuk melihat semua catatan.<?php else: ?>Belum ada perjalanan dicatat. Klik Catat perjalanan, lalu pilih penempatan PKL siswa.<?php endif; ?></td></tr><?php endif; ?></tbody></table></div>
<?php if($pages>1):$start=max(1,min($page-4,$pages-9));$end=min($pages,$start+9); ?><nav class="pagination" aria-label="Halaman perjalanan"><?php if($page>1): ?><a href="<?= e(base_url('panel/biaya-perjalanan/?'.http_build_query($filters+['page'=>$page-1]))) ?>">Sebelumnya</a><?php endif; ?><?php for($n=$start;$n<=$end;$n++): ?><a href="<?= e(base_url('panel/biaya-perjalanan/?'.http_build_query($filters+['page'=>$n]))) ?>" aria-label="Halaman <?= $n ?>" <?= $n===$page?'aria-current="page"':'' ?>><?= $n ?></a><?php endfor; ?><?php if($page<$pages): ?><a href="<?= e(base_url('panel/biaya-perjalanan/?'.http_build_query($filters+['page'=>$page+1]))) ?>">Berikutnya</a><?php endif; ?></nav><?php endif; ?>
</div>
<?php panel_end($user); ?>
